/// @name Operand and text-reference tags
///@{
inline constexpr uint8_t kOpConst8 = 0;   ///< 1-byte unsigned constant.
inline constexpr uint8_t kOpConst16 = 1;   ///< 2-byte signed constant.
inline constexpr uint8_t kOpConst32 = 2;   ///< 4-byte signed constant.
inline constexpr uint8_t kOpVar = 3;   ///< 2-byte variable ID.
inline constexpr uint8_t kOpQuery = 4;   ///< Query byte and object byte.
inline constexpr uint8_t kRouteNoWait = 0x80;   ///< Route: the script goes on at once.
inline constexpr uint8_t kTransitionDefault = 0xFF;   ///< Warp: the default transition.
inline constexpr uint8_t kKeepFacing = 4;   ///< Warp / Place: facing kept.
inline constexpr uint8_t kTextAsset = 0;   ///< 4-byte asset key of a text asset.
inline constexpr uint8_t kTextInline = 1;   ///< 4-byte offset into Bank::text.
inline constexpr uint16_t kNoVar = 0xFFFF;   ///< Native without a result variable.
inline constexpr uint8_t kNoCancel = 0xFF;   ///< Choice: Back does nothing.
inline constexpr uint8_t kObjectSelf = 254;   ///< Object operand: the context's own object.
inline constexpr uint8_t kObjectPlayer = 255;   ///< Object operand: the walker.
inline constexpr uint8_t kNoSelf = 253;   ///< Context::self: no object started the script.
inline constexpr uint8_t kFacePlayer = 4;   ///< ObjectFace: towards the walker.
inline constexpr uint8_t kFaceSelf = 5;   ///< ObjectFace: towards the context's own object.
inline constexpr uint8_t kObjectCamera = 252;   ///< I4: object operand: the camera.
inline constexpr uint8_t kObjectLast = 251;   ///< I4: object operand: the object the context last gave a route.
/// C10: object operand: the selected object, the context's own object or, when the context has none, the walker
/// (a reference game's "selected object", which its field input resets to the player every frame).
inline constexpr uint8_t kObjectSelected = 250;
inline constexpr uint8_t kFaceOppositePlayer = 6;   ///< C10: ObjectFace: the direction opposite the walker's facing (whatever the geometry; a reference game's way).
inline constexpr uint8_t kWarpNoWait = 0x80;   ///< I4: Warp facing bit: the script goes on at once.
inline constexpr uint8_t kWarpFacingMask = 0x7F;   ///< I4: Warp facing bits without kWarpNoWait.
inline constexpr uint8_t kLockSelf = 0;   ///< I4: Lock / Release: the context's object (and the others' movement).
inline constexpr uint8_t kLockAll = 1;   ///< I4: Lock / Release: every object.
inline constexpr uint8_t kMessageNoWait = 1;   ///< I4: MessageEx: the script goes on while it types.
inline constexpr uint8_t kMessageInstant = 2;   ///< I4: MessageEx: typed at once.
inline constexpr uint8_t kMessageAutoScroll = 4;   ///< I4: MessageEx: scrolls on without a button.
inline constexpr uint8_t kFadeSwap = 1;   ///< I4: Fade flags: keep the palettes the scene changes meanwhile.
inline constexpr uint8_t kObjectEncounter = 249;   ///< C1: object operand: the encounter record's current side's object.
inline constexpr uint8_t kFaceEncounter = 7;   ///< C1: ObjectFace: towards the encounter record's current side's object.
inline constexpr uint8_t kEncounterSideA = 0;   ///< C1: Encounter Set: side A.
inline constexpr uint8_t kEncounterSideB = 1;   ///< C1: Encounter Set: side B.
inline constexpr uint8_t kEncounterSideCurrent = 2;   ///< C1: Encounter Set: the current side.
inline constexpr uint8_t kEncounterSideC = 3;   ///< C1b: Encounter Set / Select: side C (REF-14's third position; 2 is kEncounterSideCurrent).
inline constexpr uint16_t kEncounterNoFlag = 0xFFFF;   ///< C1: Encounter Set: no beaten flag.
inline constexpr uint8_t kEncounterHasIntro = 1;   ///< C1: Encounter Set parts / Text: the intro text.
inline constexpr uint8_t kEncounterHasDefeat = 2;   ///< C1: Encounter Set parts / Text: the defeat text.
inline constexpr uint8_t kEncounterHasCannot = 4;   ///< C1: Encounter Set parts / Text: the cannot-battle text.
inline constexpr uint8_t kEncounterHasAfter = 8;   ///< C1: Encounter Set parts: the after-script.
inline constexpr uint8_t kEncounterHasThen = 16;   ///< C1: Encounter Set parts: a script to go on in at once (the return point stays after the Set).
inline constexpr uint8_t kEncounterPair = 1;   ///< C1: Encounter mode bit: a pair battle (two battlers a side).
inline constexpr uint8_t kEncounterRematch = 2;   ///< C1: Encounter mode bit: a rematch.
inline constexpr uint8_t kEncounterNoMusic = 4;   ///< C1: Encounter mode bit: no encounter music.
inline constexpr uint8_t kMenuBack = 1;   ///< C3: Menu flag: Back answers the cancel value (else Back does nothing).
inline constexpr uint8_t kMenuFadeWait = 2;   ///< C3: Menu flag: input waits while the screen fades.
inline constexpr uint8_t kMenuAt = 4;   ///< C3: Menu flag: x and y place it (its frame's top-left cell); else the port's place.
inline constexpr uint8_t kMenuStyleDelay = 0xFF;   ///< C3: Menu delay: the port's (its style's) frames before input.
///@}

/// @name Limits
///@{
inline constexpr int kMaxStack = 32;   ///< VM call stack slots (the manifest's stack_depth is at most this).
inline constexpr int kMaxNativeArgs = 8;   ///< Arguments per native call.
inline constexpr int kMaxChoices = 8;   ///< Options of one Choice.
inline constexpr int kMaxTriggers = 16;   ///< On-frame triggers armed at once (one map).
inline constexpr int kMaxTriggerDeps = 8;   ///< Flags and variables one trigger reads.
inline constexpr int kMaxMenuItems = 16;   ///< C3: options of one Menu (a list asset's first ones).
inline constexpr uint8_t kFirstGameNameKind = 4;   ///< C4: the first game name kind (a scripts manifest's name_kinds, in order; NameKind's count).
inline constexpr int kMaxGameNameKinds = 32;   ///< C4: name kinds a scripts manifest may declare.
inline constexpr int kMaxCounters = 16;   ///< C5: counter boxes a scripts manifest may declare.
inline constexpr int kGivenParty = 0;   ///< C8: party give's result: the creature joined the party.
inline constexpr int kGivenBoxes = 1;   ///< C8: party give's result: the party was full, it went to the boxes.
inline constexpr int kGivenNone = 2;   ///< C8: party give's result: nowhere had room (or it could not be built).
inline constexpr int kNoMember = 255;   ///< C13: party count alive's slot when it leaves no member out (past every party slot).
inline constexpr int32_t kNoPlot = 0xFFFF;   ///< M6a K3: `plot at`'s answer for an object that is no plot (capsule::plots::kNoPlot).
inline constexpr int kMaxStats = 255;   ///< C6: game statistics a scripts manifest may declare (a byte each).
///@}

